    sources:[{label:'AP · latest fighting, 17 Nov 2026',url:'https://apnews.com/article/df4b867cf8f70e88843d8fefea5d643c'},{label:'UN · conflict context and invasion',url:'https://ukraine.un.org/sites/default/files/2023-12/CCA%20Ukraine%202023_final_November%202023.pdf'}]
